import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
public final class CompanionWindMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",A=P+"NativeAreaMaterialAction",B=P+"BattleCompanion",H=P+"NativeCompanionWindAction",S=P+"NativeCompanionWindState",W=P+"BattleSpellCatalog$WindShackleSpell";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static void patch(ClassNode c){int count=0;
  if(c.name.equals(A)){for(var m:c.methods)if(m.name.equals("run"))for(var n:m.instructions)if(n instanceof MethodInsnNode v&&v.owner.equals(P+"NativeCompanionForestArea")&&v.name.equals("run")){v.owner=H;count++;}if(count!=1)throw new AssertionError("one area run");return;}
  if(c.name.equals(B)){c.fields.add(new FieldNode(ACC_PRIVATE,"nativeCompanionWindStatus","L"+P+"BattleWindShackleStatus;",null,null));int attack=0,cancel=0,clear=0;for(var m:c.methods)for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v){
    if(m.name.equals("beginStrike")&&m.desc.startsWith("(IIIJ")&&v.owner.equals(B)&&v.name.equals("effectiveAttackIntervalMillis")){var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(new VarInsnNode(LLOAD,4));add.add(new MethodInsnNode(INVOKESTATIC,S,"interval","(IL"+B+";J)I",false));m.instructions.insert(n,add);attack++;}
    if(m.name.equals("cancelMagicEffects")&&v.owner.equals(P+"NativeCompanionForestCancellation")&&v.name.equals("cancel")){var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(new MethodInsnNode(INVOKESTATIC,S,"cancel","(L"+B+";)V",false));m.instructions.insert(n,add);cancel++;}
    if(v.owner.equals(P+"BattleTimedStatus")&&v.name.equals("clear")&&prev(n) instanceof FieldInsnNode f&&f.owner.equals(B)&&f.name.equals("timedStatus")){var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(new MethodInsnNode(INVOKESTATIC,S,"clear","(L"+B+";)V",false));if((m.access&ACC_SYNCHRONIZED)==0)throw new AssertionError("unowned reset "+m.name);m.instructions.insert(n,add);clear++;}
   }if(attack!=1||cancel!=1||clear!=7)throw new AssertionError("NPC interval/cancel/clear ports "+attack+" "+cancel+" "+clear);return;}
  int selection=0,admit=0,apply=0,alias=0;for(var m:new ArrayList<>(c.methods)){
   if(m.name.equals("combatProbability$14")){var q=new MethodNode(ACC_STATIC,"nativeCompanionWindChance",m.desc,null,m.exceptions.toArray(String[]::new));m.accept(q);c.methods.add(q);alias++;}
   if(m.name.equals("nativeMaterialAreaWindBody")){int temp=m.maxLocals;for(var n:m.instructions.toArray()){
     if(n instanceof VarInsnNode load&&load.getOpcode()==ILOAD&&load.var==21){var next=n.getNext();if(next instanceof JumpInsnNode jump&&jump.getOpcode()==IFEQ){ // final selectedRange branch, followed by caster coordinate loads
       var q=next.getNext();while(q!=null&&q.getOpcode()<0)q=q.getNext();if(q instanceof VarInsnNode caster&&caster.getOpcode()==ALOAD&&caster.var==0){var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(new VarInsnNode(ALOAD,4));add.add(new MethodInsnNode(INVOKEVIRTUAL,P+"Protocol$AttackSpellRequest","targetObjectId","()J",false));for(int local:new int[]{21,19,20})add.add(new VarInsnNode(ILOAD,local));add.add(new MethodInsnNode(INVOKESTATIC,H,"select","(L"+PC+";JZII)[I",false));add.add(new VarInsnNode(ASTORE,temp));int index=0;for(int local:new int[]{21,19,20}){add.add(new VarInsnNode(ALOAD,temp));add.add(new InsnNode(ICONST_0+index++));add.add(new InsnNode(IALOAD));add.add(new VarInsnNode(ISTORE,local));}m.instructions.insertBefore(load,add);selection++;}
      }}
     if(n instanceof MethodInsnNode v&&v.owner.equals(A)&&v.name.equals("admit")){var add=new InsnList();add.add(new VarInsnNode(ALOAD,4));add.add(new MethodInsnNode(INVOKEVIRTUAL,P+"Protocol$AttackSpellRequest","targetObjectId","()J",false));m.instructions.insertBefore(n,add);v.owner=H;v.desc=v.desc.replace(")Z","J)Z");admit++;}
     if(n instanceof VarInsnNode load&&load.getOpcode()==ALOAD&&load.var==16){ // original effect-list load, before its Source filter
      boolean effects=false;for(var q=m.instructions.getFirst();q!=load;q=q.getNext())if(q instanceof VarInsnNode z&&z.getOpcode()==ISTORE&&z.var==38)effects=true;if(effects){var start=load; // Source filter now sits between the list load and iterator
       var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(new VarInsnNode(ALOAD,2));add.add(new VarInsnNode(ALOAD,4));add.add(new MethodInsnNode(INVOKEVIRTUAL,P+"Protocol$AttackSpellRequest","targetObjectId","()J",false));for(int local:new int[]{26,27,30,3})add.add(new VarInsnNode(ILOAD,local));add.add(new VarInsnNode(LLOAD,33));add.add(new MethodInsnNode(INVOKESTATIC,H,"apply","(L"+PC+";L"+W+";JIIIIJ)[I",false));add.add(new VarInsnNode(ASTORE,temp));for(int i=0;i<2;i++){add.add(new VarInsnNode(ILOAD,37+i));add.add(new VarInsnNode(ALOAD,temp));add.add(new InsnNode(ICONST_0+i));add.add(new InsnNode(IALOAD));add.add(new InsnNode(IADD));add.add(new VarInsnNode(ISTORE,37+i));}m.instructions.insertBefore(start,add);apply++;}
     }
    }m.maxLocals=Math.max(m.maxLocals,temp+1);
   }
  }if(selection!=1||admit!=1||apply!=1||alias!=1)throw new AssertionError("167 ports "+selection+" "+admit+" "+apply+" "+alias);
 }
 public static void main(String[]a)throws Exception{try(var j=new JarFile(a[1])){for(String n:List.of(PC,A,B)){var c=read(j,n);patch(c);var b=bytes(c);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(n+".class");Files.createDirectories(p.getParent());Files.write(p,b);}else try(var other=new JarFile(a[2])){if(!Arrays.equals(b,bytes(read(other,n))))throw new AssertionError(n);}}}System.out.println("PASS bounded controlled NPC167 selection/admission/effect ports, original probability clone and original clock extension");}
}
